    is_function: bool,
    a: i32,
    b: i32,

pub fn only(of_type: bool) NthSelectorData {
            return NthSelectorData{ .ty = (if (of_type) NthType.only_of_type else NthType.only_child), .is_function = false, .a = 0, .b = 1 };
    }

pub fn first(of_type: bool) NthSelectorData {
            return NthSelectorData{ .ty = (if (of_type) NthType.of_type else NthType.child), .is_function = false, .a = 0, .b = 1 };
    }

pub fn last(of_type: bool) NthSelectorData {
            return NthSelectorData{ .ty = (if (of_type) NthType.last_of_type else NthType.last_child), .is_function = false, .a = 0, .b = 1 };
    }

pub fn writeStart(self: NthSelectorData, dest: *Printer, is_function: bool) PrintErr!void {
            _ = try dest.writeStr((switch (self.ty) {
.child => (if (is_function) ":nth-child(" else ":first-child"),
.last_child => (if (is_function) ":nth-last-child(" else ":last-child"),
.of_type => (if (is_function) ":nth-of-type(" else ":first-of-type"),
.last_of_type => (if (is_function) ":nth-last-of-type(" else ":last-of-type"),
.only_child => ":only-child",
.only_of_type => ":only-of-type",
.col => ":nth-col(",
.last_col => ":nth-last-col(",
}));
    }

pub fn isFunction(self: NthSelectorData) bool {
            return ((self.a != 0) or (self.b != 1));
    }

pub fn numberSign(num: i32) []const u8 {
            if ((num >= 0)) {
                return "+";
            }
            return "";
    }

pub fn writeAffine(self: NthSelectorData, dest: *Printer) PrintErr!void {
            if (((self.a == 0) and (self.b == 0))) {
                _ = try dest.writeChar(48);
            } else {
                if (((self.a == 1) and (self.b == 0))) {
                    _ = try dest.writeChar(110);
                } else {
                    if (((self.a == -1) and (self.b == 0))) {
                        _ = try dest.writeStr("-n");
                    } else {
                        if ((self.b == 0)) {
                            _ = try dest.writeFmt("{d}n", .{ self.a });
                        } else {
                            if (((self.a == 2) and (self.b == 1))) {
                                _ = try dest.writeStr("odd");
                            } else {
                                if ((self.a == 0)) {
                                    _ = try dest.writeFmt("{d}", .{ self.b });
                                } else {
                                    if ((self.a == 1)) {
                                        _ = try dest.writeFmt("n{s}{d}", .{ NthSelectorData.numberSign(self.b), self.b });
                                    } else {
                                        if ((self.a == -1)) {
                                            _ = try dest.writeFmt("-n{s}{d}", .{ NthSelectorData.numberSign(self.b), self.b });
                                        } else {
                                            _ = try dest.writeFmt("{}n{s}{d}", .{ self.a, NthSelectorData.numberSign(self.b), self.b });
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
