        return spec.toU32();
}

pub fn compute_complex_selector_specificity(comptime Impl: type, iter: []const GenericComponent(Impl)) Specificity {
        var specificity: Specificity = .{};
        _ = &specificity;
        var si: usize = 0;
        _ = &si;
        while ((si < iter.len)) {
            _ = compute_simple_selector_specificity(Impl, (&iter[@as(usize, @intCast(si))]), (&specificity));
            si = (si + 1);
        }
        return specificity;
}

pub fn compute_simple_selector_specificity(comptime Impl: type, simple_selector: *const GenericComponent(Impl), specificity: *Specificity) void {
        switch (simple_selector.*) {
.combinator => {
_ = bun.unreachablePanic("Found combinator in simple selectors vector?", .{});
},
.part, .pseudo_element, .local_name => {
specificity.element_selectors = (specificity.element_selectors + 1);
},
.slotted => |selector| {
specificity.element_selectors = (specificity.element_selectors + 1);
        _ = specificity.add(Specificity.fromU32(selector.specificity()));
},
.host => |maybe_selector| {
specificity.class_like_selectors = (specificity.class_like_selectors + 1);
        if (maybe_selector) |selector| {
            _ = &selector;
            _ = specificity.add(Specificity.fromU32(selector.specificity()));
        }
},
.id => {
specificity.id_selectors = (specificity.id_selectors + 1);
},
.class, .attribute_in_no_namespace, .attribute_in_no_namespace_exists, .attribute_other, .root, .empty, .scope, .nth, .non_ts_pseudo_class => {
specificity.class_like_selectors = (specificity.class_like_selectors + 1);
},
.nth_of => |nth_of_data| {
specificity.class_like_selectors = (specificity.class_like_selectors + 1);
        var max: u32 = 0;
        _ = &max;
        var ni: usize = 0;
        _ = &ni;
        while ((ni < nth_of_data.selectors.len)) {
            max = @max(nth_of_data.selectors[@as(usize, @intCast(ni))].specificity(), max);
            ni = (ni + 1);
        }
        _ = specificity.add(Specificity.fromU32(max));
},
.negation, .is, .any => {
const list: []GenericSelector(Impl) = (switch (simple_selector.*) {
.negation => |list| list,
.is => |list| list,
.any => |a| a.selectors,
else => unreachable,
});
        var max: u32 = 0;
        _ = &max;
        var li: usize = 0;
        _ = &li;
        while ((li < list.len)) {
            max = @max(list[@as(usize, @intCast(li))].specificity(), max);
            li = (li + 1);
        }
        _ = specificity.add(Specificity.fromU32(max));
},
.where, .has, .explicit_universal_type, .explicit_any_namespace, .explicit_no_namespace, .default_namespace, .namespace => {

},
.nesting => {

},
}
}

