},
.delim => |d| {
switch (d) {
'>' => {
if ((parser.deepCombinatorEnabled() and input.tryParse((struct {

pub fn parseFn(self: @This(), i: *css.Parser) Result(void) {
        _ = self;
            if (i.expectDelim(62).asErr()) |e| {
                _ = &e;
                return .{ .err = e };
            }
            return i.expectDelim(62);
    }
}).parseFn, .{}).isOk())) {
