pub fn parseFn(self: @This(), i: *css.Parser) Result(void) {
        _ = self;
            if (i.expectIdentMatching("deep").asErr()) |e| {
                _ = &e;
                return .{ .err = e };
            }
            return i.expectDelim(47);
    }
}).parseFn, .{}).isOk()) {
                        combinator = .deep;
                        break;
                    } else {
                        break :outer_loop;
                    }
                }
},
else => {

},
}
},
else => {

},
}
                _ = input.reset((&before_this_token));
                if (any_whitespace) {
                    combinator = .descendant;
                    break;
                } else {
                    break :outer_loop;
                }
